// Deterministic screening of every customer row against the OFAC list. There is no model here on
// purpose: a name either matches the list or it does not, and a model would add a confident
// opinion with nothing behind it.
const policy = $('Screening Settings').first().json;
const sdn = $('Download The Sanctions List').first().json;
const alt = $('Download The Alias List').first().json;
const sdnText = typeof sdn.data === 'string' ? sdn.data : '';
const altText = typeof alt.data === 'string' ? alt.data : '';

const threshold = Number(policy.match_threshold) || 85;
const nameColumn = String(policy.customer_name_column || 'Customer Name');
const idColumn = String(policy.customer_id_column || 'Customer ID');
const escalateAfter = Number(policy.escalate_after_days) || 3;

// A clearance is a HUMAN decision about one exact pair of names, and it must survive every later
// run or the reviewer is asked the same question every night. Keyed on a STRICTER form that KEEPS
// the company suffix (error A8): ACME TRADING GMBH and ACME TRADING CO are not the same company,
// and clearing one must never clear the other.
function strictNorm(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toUpperCase().replace(/[^A-Z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
}
const clearedFor = {};
for (const item of $('Read The Reviewed Matches').all()) {
  const c = item.json || {};
  const who = strictNorm(c['Customer Name']);
  const what = strictNorm(c['Matched Name']);
  if (!who || !what) continue;
  clearedFor[who + ' >> ' + what] = {
    by: String(c['Cleared By'] || 'a reviewer'),
    reason: String(c['Reason'] || ''),
  };
}

// ---- normalisation. Uppercase, strip accents and punctuation, drop the corporate suffixes that
// make two unrelated companies look similar, collapse whitespace.
const SUFFIXES = ['LIMITED','LTD','LLC','INC','INCORPORATED','CORP','CORPORATION','COMPANY','CO',
                  'GMBH','AG','SA','SAS','SARL','BV','NV','PLC','PTE','PTY','OOO','OAO','ZAO',
                  'JSC','LLP','SPA','SRL','AB','AS','OY','KFT','DOO','SL'];
function norm(s) {
  let t = String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  t = t.toUpperCase();
  // Collapse dotted abbreviations BEFORE punctuation is stripped (error A6).
  t = t.replace(/\b(?:[A-Z]\.){2,}/g, function (m) { return m.replace(/\./g, ''); });
  t = t.replace(/[^A-Z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const parts = t.split(' ').filter(w => w.length > 1 && SUFFIXES.indexOf(w) === -1);
  return parts.join(' ');
}
function tokens(s) { return norm(s).split(' ').filter(Boolean); }

// ---- parse the two public CSVs. Both are quoted CSV with no header row.
function parseCsv(text) {
  const rows = []; let row = [], field = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') q = false;
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c !== '\r') field += c;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

const listRows = sdnText ? parseCsv(sdnText) : [];
const aliasRows = altText ? parseCsv(altText) : [];

// ---- FAIL CLOSED (error A9). A list we could not read is not an all clear, and that applies to
// BOTH files. With the alias file missing, PDVSA scores zero against a list that still holds
// PETROLEOS DE VENEZUELA, S.A.
const minList = Number(policy.min_list_rows || 1000);
const minAlias = Number(policy.min_alias_rows || 1000);
const missing = [];
if (listRows.length <= minList) missing.push('the sanctions list (' + listRows.length + ' rows)');
if (aliasRows.length <= minAlias) missing.push('the alias list (' + aliasRows.length + ' rows)');

// ---- index the list: primary names from sdn.csv, alternates from alt.csv
const entries = [];
if (!missing.length) {
  for (const r of listRows) {
    if (r.length < 4) continue;
    const nm = String(r[1] || '').trim();
    if (!nm || nm === '-0-') continue;
    entries.push({ id: String(r[0] || '').trim(), name: nm,
                   type: String(r[2] || '').trim().replace('-0-', 'entity'),
                   program: String(r[3] || '').trim() });
  }
  for (const r of aliasRows) {
    if (r.length < 4) continue;
    const nm = String(r[3] || '').trim();
    if (!nm || nm === '-0-') continue;
    entries.push({ id: String(r[0] || '').trim(), name: nm, type: 'alias', program: '' });
  }
}

const screenedAt = new Date().toISOString();
const out = [];

for (const item of $input.all()) {
  const row = item.json || {};
  const customerName = String(row[nameColumn] || '').trim();
  const customerId = String(row[idColumn] || '').trim();

  // Every key is emitted on every branch, null where there is nothing to say (error A21).
  const base = {
    customer_name: customerName,
    customer_id: customerId,
    row_number: row.row_number !== undefined ? row.row_number : null,
    screened_at: screenedAt,
    screening_status: null,
    screening_detail: null,
    best_score: 0,
    matched_name: null,
    matched_parties: 0,
    matched_spellings: 0,
    list_rows: entries.length,
    is_hit: false,
    // every key on every branch (error A21), including the triage ones
    cleared_by: null,
    cleared_reason: null,
    first_flagged_at: null,
    days_open: 0,
    is_overdue: false,
    route: 'clear',
  };

  if (missing.length) {
    out.push({ json: Object.assign({}, base, {
      route: 'hit',
      screening_status: 'NOT SCREENED',
      screening_detail: 'could not read ' + missing.join(' and ') + '. This row was NOT screened '
        + 'and this is not a clear result. Treat the customer as unscreened until a run succeeds.',
      is_hit: true,
    }) });
    continue;
  }
  if (!customerName) {
    out.push({ json: Object.assign({}, base, {
      screening_status: 'NO NAME',
      screening_detail: 'the row has no value in the ' + nameColumn + ' column, so nothing was screened.',
    }) });
    continue;
  }

  const qNorm = norm(customerName);
  const qTok = tokens(customerName);
  if (!qNorm || !qTok.length) {
    out.push({ json: Object.assign({}, base, {
      screening_status: 'NO NAME',
      screening_detail: 'the name reduced to nothing once punctuation and company suffixes were removed.',
    }) });
    continue;
  }

  const found = [];
  for (const e of entries) {
    const eNorm = norm(e.name);
    if (!eNorm) continue;
    let score = 0;
    if (eNorm === qNorm) score = 100;
    else {
      // Both directions (error A7).
      const eTok = eNorm.split(' ');
      const eSet = {};
      for (const t of eTok) eSet[t] = true;
      let hit = 0;
      for (const t of qTok) if (eSet[t]) hit++;
      score = Math.round((200 * hit) / (qTok.length + eTok.length));
      // A listing containing your whole name is always worth showing (error A10).
      if (hit === qTok.length && qTok.length >= 2 && score < threshold) score = threshold;
    }
    if (score >= threshold) found.push({ id: e.id, name: e.name, program: e.program, score: score });
  }
  found.sort(function (a, c) { return c.score - a.score; });

  if (!found.length) {
    out.push({ json: Object.assign({}, base, {
      route: 'clear',
      screening_status: 'NO MATCH',
      screening_detail: 'no entry scored ' + threshold + ' or above out of ' + entries.length
        + ' names and aliases checked. This is a name check only.',
    }) });
    continue;
  }

  // Distinct PARTIES, not matching rows (error A11).
  const ids = {};
  for (const f of found) ids[f.id] = true;
  const parties = Object.keys(ids).length;

  // A match a human already looked at and cleared STAYS cleared, and says who and why. Without
  // this the same false positive is raised every single night and the alert stops being read.
  const who = strictNorm(customerName);
  const open = found.filter(f => !clearedFor[who + ' >> ' + strictNorm(f.name)]);
  const clearance = open.length ? null : clearedFor[who + ' >> ' + strictNorm(found[0].name)];

  if (!open.length) {
    out.push({ json: Object.assign({}, base, {
      route: 'clear',
      screening_status: 'CLEARED BY REVIEW',
      screening_detail: found.length + ' spelling(s) matched, and every one was already reviewed '
        + 'and cleared for this exact name by ' + clearance.by
        + (clearance.reason ? ': ' + clearance.reason : '') + '.',
      best_score: found[0].score,
      matched_name: found[0].name + (found[0].program ? ' [' + found[0].program + ']' : ''),
      matched_parties: parties,
      matched_spellings: found.length,
      cleared_by: clearance.by,
      cleared_reason: clearance.reason || null,
      is_hit: false,
    }) });
    continue;
  }

  // How long has this hit been sitting unreviewed? An open sanctions match nobody has looked at
  // is the failure this template exists to prevent, so it escalates rather than waiting quietly.
  const firstSeenRaw = String(row['First Flagged At'] || '').trim();
  const firstSeen = firstSeenRaw || screenedAt;
  const daysOpen = Math.max(0, Math.floor(
    (Date.parse(screenedAt) - Date.parse(firstSeen)) / 86400000));
  const overdue = firstSeenRaw !== '' && daysOpen >= escalateAfter;

  const openIds = {};
  for (const f of open) openIds[f.id] = true;

  out.push({ json: Object.assign({}, base, {
    route: overdue ? 'escalate' : 'hit',
    screening_status: 'POSSIBLE MATCH',
    screening_detail: Object.keys(openIds).length + ' listed part(y/ies) matched under '
      + open.length + ' spelling(s) at ' + threshold + ' or above. This is a candidate list, not '
      + 'a finding. A person must compare identifiers before acting.'
      + (overdue ? ' OPEN FOR ' + daysOpen + ' DAYS WITHOUT A REVIEW.' : ''),
    best_score: open[0].score,
    matched_name: open[0].name + (open[0].program ? ' [' + open[0].program + ']' : ''),
    matched_parties: Object.keys(openIds).length,
    matched_spellings: open.length,
    first_flagged_at: firstSeen,
    days_open: daysOpen,
    is_overdue: overdue,
    is_hit: true,
  }) });
}

return out;

// What this run FOUND. Deliberately worded as found, not written: this node runs alongside the
// two Google Sheets writes rather than after them, so it must not claim a write it cannot see.
const rows = $input.all().map(i => i.json);
const hits = rows.filter(r => r.screening_status === 'POSSIBLE MATCH');
const unscreened = rows.filter(r => r.screening_status === 'NOT SCREENED');
const noName = rows.filter(r => r.screening_status === 'NO NAME');
const clearedByReview = rows.filter(r => r.screening_status === 'CLEARED BY REVIEW');
const overdue = rows.filter(r => r.is_overdue === true);

const lines = hits.slice(0, 10).map(function (h) {
  return '- ' + h.customer_name + ' -> ' + h.matched_name + ' (score ' + h.best_score + ')';
});

return [{ json: {
  screened_rows: rows.length,
  hit_rows: hits.length,
  cleared_by_review_rows: clearedByReview.length,
  overdue_rows: overdue.length,
  unscreened_rows: unscreened.length,
  no_name_rows: noName.length,
  list_rows: rows.length ? rows[0].list_rows : 0,
  needs_telling: hits.length > 0 || unscreened.length > 0 || overdue.length > 0,
  summary_text: (unscreened.length
      ? ':warning: ' + unscreened.length + ' row(s) were NOT screened because an OFAC file could '
        + 'not be read. Treat them as unscreened.\n'
      : '')
    + (overdue.length
      ? ':rotating_light: ' + overdue.length + ' hit(s) have been open without a review for '
        + 'longer than the escalation window.\n'
      : '')
    + (clearedByReview.length
      ? clearedByReview.length + ' match(es) were suppressed because a reviewer already cleared '
        + 'them.\n'
      : '')
    + (hits.length
      ? hits.length + ' of ' + rows.length + ' customers matched the OFAC list at or above the '
        + 'threshold. These are candidates, not findings:\n' + lines.join('\n')
        + (hits.length > 10 ? '\n...and ' + (hits.length - 10) + ' more in the sheet.' : '')
      : 'No customer matched the OFAC list in this run. ' + rows.length + ' row(s) screened.'),
} }];
